"""Planned workflow: generated by Claude from the request, cached per run and per workflow."""

from __future__ import annotations

import hashlib
import json
from datetime import timedelta
from typing import Any

from sqlalchemy import select, update
from sqlalchemy.orm import Session

from app.anthropic_client import PLAN_KINDS, PLAN_SERVICES, ManagedAgentsError
from app.deps import get_user_settings
from app.models import Connector, Skill, User, Workflow, WorkflowRun, utcnow
from app.settings.service import client_for
from app.workflows.compose import compose_workflow_message, snapshot_skills

GENERATING_TIMEOUT = timedelta(minutes=3)
MAX_STEPS = 10

PlanTarget = WorkflowRun | Workflow


def connector_policies(db: Session, user: User) -> dict[str, str]:
    """{provider: permission_policy} for the user's connected services."""
    rows = db.scalars(
        select(Connector).where(Connector.user_id == user.id, Connector.credential_id.is_not(None))
    )
    return {c.provider: c.permission_policy for c in rows}


def request_text(db: Session, target: PlanTarget) -> str:
    """Exact text the agent receives (workflows: current active skills + content)."""
    if isinstance(target, WorkflowRun):
        return target.initial_message
    skills = snapshot_skills(db.scalars(select(Skill)))
    return compose_workflow_message(skills, target.name, target.content)


def plan_hash(text: str, model: str, policies: dict[str, str]) -> str:
    payload = json.dumps([text, model, sorted(policies.items())], ensure_ascii=False)
    return hashlib.sha256(payload.encode()).hexdigest()


def normalize(raw: dict[str, Any], policies: dict[str, str]) -> dict[str, Any]:
    """Clean Claude's output and compute approvals ourselves (never trusted from the model)."""
    steps: list[dict[str, Any]] = []
    for item in (raw.get("steps") or [])[:MAX_STEPS]:
        if not isinstance(item, dict):
            continue
        kind = item.get("kind") if item.get("kind") in PLAN_KINDS else "reasoning"
        service = item.get("service") if item.get("service") in PLAN_SERVICES else "none"
        uses_mcp = service in {"linear", "github", "atlassian"} and kind in {"read", "action"}
        steps.append(
            {
                "title": str(item.get("title") or "Step").strip()[:60],
                "detail": str(item.get("detail") or "").strip()[:90],
                "kind": kind,
                "service": service,
                # Every MCP call on an "Always ask" connector pauses for your approval.
                "needs_approval": uses_mcp and policies.get(service) == "always_ask",
                # The agent cannot use a service you have not connected.
                "missing_connector": uses_mcp and service not in policies,
            }
        )
    if not steps or steps[-1]["kind"] != "result":
        steps.append(
            {"title": "Final result", "detail": "", "kind": "result", "service": "none",
             "needs_approval": False, "missing_connector": False}
        )
    return {"summary": str(raw.get("summary") or "").strip()[:240], "steps": steps}


def _claim(db: Session, target: PlanTarget, digest: str) -> bool:
    """Atomically mark the target as `generating`. False if another request is already on it."""
    model = type(target)
    stale = utcnow() - GENERATING_TIMEOUT
    res = db.execute(
        update(model)
        .where(
            model.id == target.id,
            (model.plan_status.is_(None))
            | (model.plan_status != "generating")
            | (model.plan_updated_at < stale),
        )
        .values(plan_status="generating", plan_hash=digest, plan_error=None, plan_updated_at=utcnow())
    )
    db.commit()
    db.refresh(target)
    return res.rowcount == 1  # type: ignore[attr-defined]


def _reuse_workflow_plan(db: Session, run: WorkflowRun, digest: str) -> bool:
    """A run started from a workflow reuses the workflow's plan when the request is identical."""
    wf = run.workflow
    if wf is None or wf.plan_status != "ready" or wf.plan_hash != digest or not wf.plan_json:
        return False
    run.plan_json, run.plan_hash, run.plan_status = wf.plan_json, digest, "ready"
    run.plan_error, run.plan_updated_at = None, utcnow()
    db.commit()
    return True


def ensure_plan(db: Session, user: User, target: PlanTarget, force: bool = False) -> None:
    """Generate the plan if needed. Runs keep their first plan; workflows follow their content."""
    settings = get_user_settings(db, user)
    policies = connector_policies(db, user)
    text = request_text(db, target)
    digest = plan_hash(text, settings.model, policies)

    if not force and target.plan_status == "ready":
        if isinstance(target, WorkflowRun) or target.plan_hash == digest:
            return
    if not force and target.plan_status == "failed" and target.plan_hash == digest:
        return  # wait for an explicit retry
    if isinstance(target, WorkflowRun) and not force and _reuse_workflow_plan(db, target, digest):
        return
    if not _claim(db, target, digest):
        return  # another request is generating it
    try:
        raw = client_for(settings).generate_plan(settings.model, text, sorted(policies))
        target.plan_json = normalize(raw, policies)
        target.plan_status = "ready"
    except (ManagedAgentsError, RuntimeError) as exc:
        target.plan_status = "failed"
        target.plan_error = str(exc)
    target.plan_updated_at = utcnow()
    db.commit()
